-- Consultant directory: the public profile of a Consultant lives on the platform's own Consultant profile.
-- One source for every surface: the public site, coordinator routing and every later stage read the same
-- practitioner_profiles row, its care area from the care_categories lookup. A doctor shown publicly therefore always
-- exists as a platform profile. Content is CV-sourced, bilingual JSON (text, for H2 and PostgreSQL alike); the care
-- area and its label are never stored here. Pre-production clean cutover: the frontend's static profile files are
-- removed and these rows replace them.
CREATE TABLE consultant_directory_profiles (
    practitioner_id UUID PRIMARY KEY REFERENCES practitioner_profiles(id),
    slug VARCHAR(80) NOT NULL,
    published BOOLEAN NOT NULL,
    sort_order INTEGER NOT NULL,
    content_en TEXT NOT NULL,
    content_ar TEXT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    version BIGINT NOT NULL DEFAULT 0,
    CONSTRAINT uq_consultant_directory_slug UNIQUE (slug)
);

-- The Consultants already presented on the site. A profile that already exists (same display name) is reused; the
-- rest are created as Consultant profiles under credential review, with no sign-in yet, so they are listed but not
-- eligible for cases until credentialing, availability and the affiliation declaration are complete.

INSERT INTO practitioner_profiles(id, legal_name, display_name, specialty, care_category, practitioner_type, credentialing_status, account_status, languages, created_at, updated_at, version)
